import{_ as s,C as n,c as a,o as i,a3 as e,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Manufacturing order costs","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/basic-setup/manufacturing-order-costs.md","filePath":"master/supply-chain/manufacturing/basic-setup/manufacturing-order-costs.md","lastUpdated":1793074831000}'),d={name:"master/supply-chain/manufacturing/basic-setup/manufacturing-order-costs.md"};function c(l,t,h,u,g,m){const o=n("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="manufacturing-order-costs" tabindex="-1">Manufacturing order costs <a class="header-anchor" href="#manufacturing-order-costs" aria-label="Permalink to &quot;Manufacturing order costs&quot;">​</a></h1><p>Every manufacturing order has a cost. It is the price of the components plus the cost of the work done at the work centers. Aureus shows this cost on two pages before you make anything: the BoM <strong>Overview</strong> and the MO <strong>Overview</strong>. You can then check that a product earns a margin.</p><blockquote><p><strong>In simple words:</strong> Parts cost plus work cost, shown per order and per unit.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Operation costs need <strong>Work Orders</strong> on in <code>Manufacturing → Settings → Manage Operations</code>. Each work center also needs a value in <strong>Cost per Hour</strong>. See <a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a>.</p><h2 id="where-costs-come-from" tabindex="-1">Where costs come from <a class="header-anchor" href="#where-costs-come-from" aria-label="Permalink to &quot;Where costs come from&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Source</th></tr></thead><tbody><tr><td>Components</td><td>The cost of each product, times the quantity in the BoM</td></tr><tr><td>Operations</td><td>Minutes in the operation, times the cost of its work center</td></tr></tbody></table><p>Set the work center cost here: <code>Manufacturing → Configurations → Work Centers</code>, open a work center and fill <strong>Cost per Hour</strong> in the <strong>Costing Information</strong> section. See <a href="./../advanced-configuration/work-centers.html">Work centers</a>.</p>',8)),r(o,{src:"/images1/manufacturing/cost_work_center_cost_per_hour.png",alt:"Work center Assembly Station edit form, Costing Information section with Cost per Hour filled in"}),t[1]||(t[1]=e('<h2 id="bom-overview" tabindex="-1">BoM Overview <a class="header-anchor" href="#bom-overview" aria-label="Permalink to &quot;BoM Overview&quot;">​</a></h2><p>The BoM <strong>Overview</strong> shows what one recipe costs before any order exists.</p><ol><li>Open <code>Manufacturing → Products → Bills of Materials</code>.</li><li>Click <strong>BOM-MC-LAPTOP</strong>, then the <strong>Overview</strong> tab.</li><li>Use the <strong>Quantity</strong> and <strong>Variant</strong> filters to change the size.</li></ol>',3)),r(o,{src:"/images1/manufacturing/cost_bom_overview.png",alt:"BoM Overview of BOM-MC-LAPTOP showing Free to Use, On Hand, Total Cost and the table Product, Quantity, Lead Time, Route, BoM Cost, Product Cost, with operations in minutes"}),t[2]||(t[2]=e('<p>The page shows <strong>Free to Use</strong>, <strong>On Hand</strong> and <strong>Total Cost</strong>. The table lists each component with <strong>BoM Cost</strong> and <strong>Product Cost</strong>. Operations appear as minutes.</p><h2 id="mo-overview" tabindex="-1">MO Overview <a class="header-anchor" href="#mo-overview" aria-label="Permalink to &quot;MO Overview&quot;">​</a></h2><p>The MO <strong>Overview</strong> shows costs for one order.</p><ol><li>Open <code>Manufacturing → Operations → Manufacturing Orders</code>.</li><li>Click <strong>MO/2</strong>, then the <strong>Overview</strong> tab.</li></ol>',4)),r(o,{src:"/images1/manufacturing/cost_mo_overview.png",alt:"MO/2 Overview page, full table with the Operations rows and the Unit Cost row visible"}),t[3]||(t[3]=e('<p>Columns:</p><ul><li><strong><em>Status:</em></strong> Whether the item is confirmed, and whether stock is available.</li><li><strong><em>Quantity:</em></strong> The amount this order needs.</li><li><strong><em>Free to use / On Hand:</em></strong> Stock you can still reserve, and stock in the warehouse.</li><li><strong><em>Reserved:</em></strong> Stock already held for this order.</li><li><strong><em>Receipt:</em></strong> <strong>Available</strong> or an expected date.</li><li><strong><em>Unit Cost:</em></strong> Cost of one unit of the line.</li><li><strong><em>MO Cost:</em></strong> Cost planned for this order.</li><li><strong><em>BoM Cost:</em></strong> Cost taken from the recipe.</li><li><strong><em>Real Cost:</em></strong> Cost recorded when the work is done.</li></ul><h2 id="bom-cost-mo-cost-and-real-cost" tabindex="-1">BoM cost, MO cost and real cost <a class="header-anchor" href="#bom-cost-mo-cost-and-real-cost" aria-label="Permalink to &quot;BoM cost, MO cost and real cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cost</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>BoM Cost</strong></td><td>What the recipe says it should cost</td></tr><tr><td><strong>MO Cost</strong></td><td>The same recipe for the quantity on this order</td></tr><tr><td><strong>Real Cost</strong></td><td>What the order actually cost</td></tr></tbody></table><p><strong>Real Cost</strong> shows <strong>$0.00</strong> while the order is only confirmed. The two planned costs match when nothing was changed on the order.</p><h2 id="expected-and-real-duration" tabindex="-1">Expected and real duration <a class="header-anchor" href="#expected-and-real-duration" aria-label="Permalink to &quot;Expected and real duration&quot;">​</a></h2><p>Each operation has an <strong>Expected Duration</strong> in minutes. It comes from the operation, times the quantity. The <strong>Real Duration</strong> is the tracked time on the work order. Compare them in the <strong>Work Orders</strong> tab of the order. See <a href="./../workflows/work-orders.html">Work orders</a>.</p><h2 id="worked-numbers-mo-2" tabindex="-1">Worked numbers: MO/2 <a class="header-anchor" href="#worked-numbers-mo-2" aria-label="Permalink to &quot;Worked numbers: MO/2&quot;">​</a></h2><p>MO/2 makes 2 <strong>Business Laptop</strong> units.</p><table tabindex="0"><thead><tr><th>Line</th><th>MO Cost</th></tr></thead><tbody><tr><td>Motherboard (2 × 1,900)</td><td>3,800</td></tr><tr><td>RAM 16GB (4 × 2,900)</td><td>11,600</td></tr><tr><td>SSD 512GB (2 × 2,100)</td><td>4,200</td></tr><tr><td>Laptop Battery (2 × 2,100)</td><td>4,200</td></tr><tr><td>LCD Screen 14-inch (2 × 4,900)</td><td>9,800</td></tr><tr><td>Laptop Chassis (2 × 2,450)</td><td>4,900</td></tr><tr><td>Components total</td><td>38,500</td></tr><tr><td>Assemble Components (120 minutes)</td><td>90</td></tr><tr><td>Test &amp; Pack (60 minutes)</td><td>30</td></tr><tr><td>Operations total (180 minutes)</td><td>120</td></tr><tr><td><strong>MO Cost</strong></td><td><strong>38,620</strong></td></tr></tbody></table><p>The <strong>Unit Cost</strong> row divides the MO cost by the quantity: 38,620 ÷ 2 = <strong>19,310</strong>.</p><p>The operation minutes come from the defaults: 60 minutes for <strong>Assemble Components</strong> and 30 for <strong>Test &amp; Pack</strong>, each times 2 units.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the unit cost looks wrong, check <strong>Cost per Hour</strong> on the work centers and the cost on each component product.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./bill-of-materials.html">Bill of materials</a></li><li><a href="./../advanced-configuration/work-centers.html">Work centers</a></li><li><a href="./../advanced-configuration/operations.html">Operations</a></li><li><a href="./../workflows/">Manufacturing order lifecycle</a></li></ul>',15))])}const b=s(d,[["render",c]]);export{f as __pageData,b as default};
